"use client";

import * as React from "react";
import { Button as ButtonPrimitive } from "@base-ui/react/button";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";
import { focusRing, glassFill, primaryFill } from "./_shared";

/**
 * Ink mail Button on a Base UI button: a 1rem-corner block in Inter semibold.
 *
 * The primary is flat off-white with black ink, the one solid bright surface
 * on the black page. The glass variant is the translucent call to action that
 * pairs with it. Secondary and outline step down through surface luminance
 * and hairlines. Nothing casts a shadow. A disabled button goes quiet whether
 * the element is a native button or a link rendered through `render`.
 */
const buttonVariants = cva(
  [
    "inline-flex max-w-full shrink-0 select-none items-center justify-center gap-2 whitespace-nowrap",
    "rounded-xl font-semibold",
    "transition-[background-color,background-image,color,border-color] duration-fast ease-out",
    focusRing,
    "disabled:pointer-events-none disabled:border-transparent disabled:bg-muted disabled:bg-none disabled:text-(--foreground-disabled)",
    "data-[disabled]:pointer-events-none data-[disabled]:border-transparent data-[disabled]:bg-muted data-[disabled]:bg-none data-[disabled]:text-(--foreground-disabled)",
    "[&_svg]:pointer-events-none [&_svg]:shrink-0",
  ].join(" "),
  {
    variants: {
      variant: {
        default: primaryFill,
        primary: primaryFill,
        glass: glassFill,
        secondary:
          "border border-(--line-strong) bg-secondary text-secondary-foreground hover:bg-muted",
        outline:
          "border border-(--line-strong) bg-background text-foreground hover:bg-secondary",
        ghost: "bg-transparent text-muted-foreground hover:bg-secondary hover:text-foreground",
        destructive:
          "bg-destructive text-destructive-foreground hover:bg-destructive/90",
        link: "h-auto rounded-sm px-0 font-medium text-(--link) underline-offset-4 hover:underline",
      },
      size: {
        sm: "h-8 px-3 text-sm",
        default: "h-10 px-4 text-sm",
        lg: "h-12 px-5 text-base",
        icon: "size-10 px-0",
        "icon-sm": "size-8 px-0",
        "icon-lg": "size-12 px-0",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  },
);

/** Props for the Base UI Button. `asChild` turns a single child element into the button. */
export interface ButtonProps
  extends
    Omit<ButtonPrimitive.Props, "className">,
    VariantProps<typeof buttonVariants> {
  className?: string;
  /**
   * Renders the single child element as the button, for callers written
   * against the Radix API (`<Button asChild><a href="…" /></Button>`).
   * Base UI composes through `render`, so the child becomes that element.
   */
  asChild?: boolean;
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant, size, asChild = false, children, ...props }, ref) => {
    const classes = cn(buttonVariants({ variant, size, className }));

    if (asChild && React.isValidElement(children)) {
      return (
        <ButtonPrimitive
          ref={ref}
          data-slot="button"
          className={classes}
          nativeButton={false}
          {...props}
          render={children}
        />
      );
    }

    return (
      <ButtonPrimitive
        ref={ref}
        data-slot="button"
        className={classes}
        {...props}
      >
        {children}
      </ButtonPrimitive>
    );
  },
);
Button.displayName = "Button";

export { Button, buttonVariants };
